-- Generated from assets-rungtiva-sol-r8.xlsx SHA-256 711ed08fba13865200e2b8c4c112c1f091d50f428e1f936cac670623d30f2978
-- Replaces the primary plant Asset master and remaps every linked CM using the user-confirmed map.
BEGIN;
SET LOCAL lock_timeout = '30s';
SET LOCAL statement_timeout = '10min';
LOCK TABLE "CmWork", "PmWork", "PmGroupAsset", "Asset", "Zone" IN SHARE ROW EXCLUSIVE MODE;

CREATE SCHEMA IF NOT EXISTS asset_r8_backup_20260912;
CREATE TABLE asset_r8_backup_20260912."Asset" AS TABLE public."Asset";
CREATE TABLE asset_r8_backup_20260912."AssetSystem" AS TABLE public."AssetSystem";
CREATE TABLE asset_r8_backup_20260912."AssetType" AS TABLE public."AssetType";
CREATE TABLE asset_r8_backup_20260912."AssetClass" AS TABLE public."AssetClass";
CREATE TABLE asset_r8_backup_20260912."AssetFamily" AS TABLE public."AssetFamily";
CREATE TABLE asset_r8_backup_20260912."AssetTechnicalField" AS TABLE public."AssetTechnicalField";
CREATE TABLE asset_r8_backup_20260912."AssetTechnicalValue" AS TABLE public."AssetTechnicalValue";
CREATE TABLE asset_r8_backup_20260912."AssetDocument" AS TABLE public."AssetDocument";
CREATE TABLE asset_r8_backup_20260912."CmWork" AS TABLE public."CmWork";
CREATE TABLE asset_r8_backup_20260912."PmWork" AS TABLE public."PmWork";
CREATE TABLE asset_r8_backup_20260912."PmGroupAsset" AS TABLE public."PmGroupAsset";
CREATE TABLE asset_r8_backup_20260912."Zone" AS TABLE public."Zone";

CREATE TEMP TABLE "_asset_r8_cm_map" ("oldAssetId" TEXT PRIMARY KEY, "oldAssetCode" TEXT NOT NULL, "targetAssetCode" TEXT NOT NULL);

CREATE TEMP TABLE "_asset_r8_incoming" (
  "id" TEXT PRIMARY KEY, "publicToken" TEXT NOT NULL, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL,
  "systemName" TEXT NOT NULL, "zoneName" TEXT NOT NULL, "assetType" TEXT NOT NULL, "assetLevel" TEXT NOT NULL,
  "parentCode" TEXT, "discipline" TEXT NOT NULL, "criticality" TEXT NOT NULL, "manufacturer" TEXT, "model" TEXT,
  "serialNumber" TEXT, "serialNormalized" TEXT, "keySpecification" TEXT, "tagKks" TEXT, "metadataJson" TEXT
);

DO $$
BEGIN
  IF (SELECT COUNT(*) FROM "_asset_r8_incoming") <> 583 THEN RAISE EXCEPTION 'R8 incoming count must be 583'; END IF;
  IF EXISTS (SELECT 1 FROM "_asset_r8_cm_map" m LEFT JOIN "Asset" a ON a."id"=m."oldAssetId" AND a."plantId"='primary-plant' WHERE a."id" IS NULL OR a."code" IS DISTINCT FROM m."oldAssetCode") THEN RAISE EXCEPTION 'Confirmed CM mapping no longer matches the current Asset master'; END IF;
  IF EXISTS (SELECT 1 FROM "_asset_r8_cm_map" m LEFT JOIN "_asset_r8_incoming" i ON i."code"=m."targetAssetCode" WHERE i."id" IS NULL) THEN RAISE EXCEPTION 'Confirmed CM mapping target is missing from R8'; END IF;
  IF EXISTS (SELECT 1 FROM "CmWork" c JOIN "Asset" a ON a."id"=c."assetId" WHERE a."plantId"='primary-plant' AND NOT EXISTS (SELECT 1 FROM "_asset_r8_cm_map" m WHERE m."oldAssetId"=a."id")) THEN RAISE EXCEPTION 'A linked CM Asset is missing from the confirmed R8 mapping'; END IF;
  IF (SELECT COUNT(*) FROM "CmWork" c JOIN "Asset" a ON a."id"=c."assetId" WHERE a."plantId"='primary-plant') <> 28 THEN RAISE EXCEPTION 'Linked CM count changed after approval'; END IF;
  IF (SELECT COUNT(DISTINCT c."assetId") FROM "CmWork" c JOIN "Asset" a ON a."id"=c."assetId" WHERE a."plantId"='primary-plant') <> 22 THEN RAISE EXCEPTION 'Linked CM Asset count changed after approval'; END IF;
  IF EXISTS (SELECT 1 FROM "PmWork" w WHERE w."plantId"='primary-plant') OR EXISTS (SELECT 1 FROM "PmGroupAsset" g WHERE g."plantId"='primary-plant') THEN RAISE EXCEPTION 'PM Asset dependency appeared after approval; migration aborted to preserve PM history'; END IF;
END $$;

CREATE TEMP TABLE "_asset_r8_cm_work_remap" AS
SELECT c."id" AS "cmWorkId", i."id" AS "newAssetId"
FROM "CmWork" c
JOIN "Asset" a ON a."id"=c."assetId" AND a."plantId"='primary-plant'
JOIN "_asset_r8_cm_map" m ON m."oldAssetId"=a."id"
JOIN "_asset_r8_incoming" i ON i."code"=m."targetAssetCode";
DO $$ BEGIN IF (SELECT COUNT(*) FROM "_asset_r8_cm_work_remap") <> 28 THEN RAISE EXCEPTION 'Expected 28 CM works in the approved remap'; END IF; END $$;

UPDATE "CmWork" c SET "assetCodeSnapshot"=a."code", "assetNameSnapshot"=COALESCE(a."nameTh",a."nameEn"), "assetId"=NULL
FROM "Asset" a WHERE c."assetId"=a."id" AND a."plantId"='primary-plant';
UPDATE "Asset" SET "parentId"=NULL WHERE "plantId"='primary-plant';
DELETE FROM "AssetTechnicalValue" v USING "Asset" a WHERE v."assetId"=a."id" AND a."plantId"='primary-plant';
DELETE FROM "AssetDocument" d USING "Asset" a WHERE d."assetId"=a."id" AND a."plantId"='primary-plant';
DELETE FROM "Asset" WHERE "plantId"='primary-plant';
DELETE FROM "AssetCodeSequence" WHERE "plantId"='primary-plant';
DELETE FROM "AssetSequence" WHERE "plantId"='primary-plant';
DELETE FROM "AssetTechnicalField" f USING "AssetType" t WHERE f."assetTypeId"=t."id" AND t."plantId"='primary-plant';
DELETE FROM "AssetType" WHERE "plantId"='primary-plant';
DELETE FROM "AssetFamily" WHERE "plantId"='primary-plant';
DELETE FROM "AssetClass" WHERE "plantId"='primary-plant';
DELETE FROM "AssetSystem" WHERE "plantId"='primary-plant';

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "Zone" WHERE "plantId"='primary-plant' AND "name"='ASH Handling') AND EXISTS (SELECT 1 FROM "Zone" WHERE "plantId"='primary-plant' AND "name"='ASH handing') THEN RAISE EXCEPTION 'Both ASH Handling Zone spellings exist'; END IF;
  IF EXISTS (SELECT 1 FROM "Zone" WHERE "plantId"='primary-plant' AND "name"='Water Treatment') AND EXISTS (SELECT 1 FROM "Zone" WHERE "plantId"='primary-plant' AND "name"='Water Treatment Plant') THEN RAISE EXCEPTION 'Both Water Treatment Zone names exist'; END IF;
END $$;
UPDATE "Zone" SET "name"='ASH Handling', "active"=TRUE, "updatedAt"=CURRENT_TIMESTAMP WHERE "plantId"='primary-plant' AND "name"='ASH handing';
UPDATE "Zone" SET "name"='Water Treatment', "active"=TRUE, "updatedAt"=CURRENT_TIMESTAMP WHERE "plantId"='primary-plant' AND "name"='Water Treatment Plant';
DO $$ BEGIN
  IF EXISTS (SELECT required.name FROM (VALUES ('ASH Handling'),('Boiler&Combustion'),('Cooling Tower'),('ESP'),('Fuel preparation'),('Turbine'),('Vehicle'),('Water Treatment')) required(name) LEFT JOIN "Zone" z ON z."plantId"='primary-plant' AND z."name"=required.name AND z."active"=TRUE WHERE z."id" IS NULL) THEN RAISE EXCEPTION 'One or more required R8 Zones are missing or inactive'; END IF;
END $$;


SELECT i."id",i."publicToken",'primary-plant',s."id",c."id",t."id",z."id",NULL,i."code",i."assetLevel",i."discipline",i."tagKks",i."keySpecification",i."metadataJson",i."name",NULL,i."manufacturer",i."model",i."serialNumber",i."serialNormalized",'IN_SERVICE',i."criticality",'ACTIVE','READY',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM "_asset_r8_incoming" i
JOIN "AssetSystem" s ON s."plantId"='primary-plant' AND s."nameTh"=i."systemName"
JOIN "AssetClass" c ON c."plantId"='primary-plant' AND c."nameTh"=i."discipline"
JOIN "AssetType" t ON t."plantId"='primary-plant' AND t."nameTh"=i."assetType"
JOIN "Zone" z ON z."plantId"='primary-plant' AND z."name"=i."zoneName" AND z."active"=TRUE;

UPDATE "Asset" child SET "parentId"=parent."id"
FROM "_asset_r8_incoming" i JOIN "Asset" parent ON parent."plantId"='primary-plant' AND parent."code"=i."parentCode"
WHERE child."id"=i."id" AND i."parentCode" IS NOT NULL;
UPDATE "CmWork" c SET "assetId"=m."newAssetId" FROM "_asset_r8_cm_work_remap" m WHERE c."id"=m."cmWorkId";

DO $$
BEGIN
  IF (SELECT COUNT(*) FROM "Asset" WHERE "plantId"='primary-plant') <> 583 THEN RAISE EXCEPTION 'R8 Asset count verification failed'; END IF;
  IF (SELECT COUNT(*) FROM "AssetSystem" WHERE "plantId"='primary-plant') <> 13 THEN RAISE EXCEPTION 'R8 System count verification failed'; END IF;
  IF (SELECT COUNT(*) FROM "AssetType" WHERE "plantId"='primary-plant') <> 21 THEN RAISE EXCEPTION 'R8 Asset Type count verification failed'; END IF;
  IF EXISTS (SELECT "code" FROM "Asset" WHERE "plantId"='primary-plant' GROUP BY "code" HAVING COUNT(*)>1) THEN RAISE EXCEPTION 'Duplicate R8 Asset code'; END IF;
  IF EXISTS (SELECT 1 FROM "_asset_r8_incoming" i JOIN "Asset" a ON a."id"=i."id" WHERE i."parentCode" IS NOT NULL AND a."parentId" IS NULL) THEN RAISE EXCEPTION 'R8 parent assignment failed'; END IF;
  IF EXISTS (SELECT 1 FROM "_asset_r8_cm_work_remap" m JOIN "CmWork" c ON c."id"=m."cmWorkId" WHERE c."assetId" IS DISTINCT FROM m."newAssetId") THEN RAISE EXCEPTION 'CM remap verification failed'; END IF;
END $$;
COMMIT;
